const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([-0.992, 52.937]).buffer(5000); // Point on Trent River near Nottingham, UK, 5km buffer

    const beforeDateStart = '2017-09-01';
    const beforeDateEnd = '2017-09-10';
    const afterDateStart = '2017-09-15';
    const afterDateEnd = '2017-09-20';

    // 2. Data Acquisition & Check
    const s1Collection = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filterBounds(roi);

    const beforeCollection = s1Collection.filterDate(beforeDateStart, beforeDateEnd);
    const afterCollection = s1Collection.filterDate(afterDateStart, afterDateEnd);

    const beforeSize = beforeCollection.size().getInfo();
    const afterSize = afterCollection.size().getInfo();

    console.log(`Images found before event: ${beforeSize}`);
    console.log(`Images found during event: ${afterSize}`);

    if (beforeSize === 0 || afterSize === 0) {
        console.log('Evidence: One or both time periods lack Sentinel-1 imagery.');
        console.log('C1');
        return;
    }

    // Create mosaics for comparison
    const beforeImage = beforeCollection.mosaic().clip(roi);
    const afterImage = afterCollection.mosaic().clip(roi);

    // 3. Processing: Create Water Masks
    // Smooth, dark areas (low backscatter) are typically water. A threshold of -16 dB is common for VV polarization.
    const waterThreshold = -16;
    const beforeWater = beforeImage.select('VV').lt(waterThreshold);
    const afterWater = afterImage.select('VV').lt(waterThreshold);

    // 4. Calculation: Count Water Pixels
    const scale = 100; // SAR data is ~10m, but 100m is fine for regional count and avoids timeouts.

    const countReducer = ee.Reducer.sum();

    const beforeCountResult = beforeWater.reduceRegion({
        reducer: countReducer,
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    });

    const afterCountResult = afterWater.reduceRegion({
        reducer: countReducer,
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    });

    const beforeWaterPixels = beforeCountResult.get('VV').getInfo();
    const afterWaterPixels = afterCountResult.get('VV').getInfo();

    if (beforeWaterPixels === null || afterWaterPixels === null) {
        console.log('Evidence: Failed to calculate water pixel counts.');
        console.log('C3');
        return;
    }

    if (beforeWaterPixels === 0 && afterWaterPixels === 0) {
        console.log('Evidence: No water pixels detected in either period after processing.');
        console.log('C2');
        return;
    }

    // 5. Validation & Final Answer
    // Flooding is defined as a significant increase in surface water. A 20% increase is a reasonable threshold.
    const increaseThreshold = 1.20; 
    const isFlooded = afterWaterPixels > (beforeWaterPixels * increaseThreshold);

    console.log(`Water Pixels (Before): ${beforeWaterPixels}`);
    console.log(`Water Pixels (During): ${afterWaterPixels}`);

    const percentageIncrease = beforeWaterPixels > 0 ? ((afterWaterPixels - beforeWaterPixels) / beforeWaterPixels) * 100 : (afterWaterPixels > 0 ? Infinity : 0);
    console.log(`Water Area Change: ${percentageIncrease.toFixed(2)}%`);

    if (isFlooded) {
        console.log('Evidence: Water pixel count increased by more than 20%, indicating potential flooding.');
        console.log('A');
    } else {
        console.log('Evidence: Water pixel count did not increase significantly.');
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log('D');
});
